/// <summary>
/// COC checks if it Trumpf production
/// </summary>
/// <param name = "_prodTable">ProdTable record</param>
/// <returns>Container [true of false, Message]</returns>
static public container isTrumpfProductionItem(ProdTable _prodTable)
{
    boolean isTrumpf;
    str message = '';

    next isTrumpfProductionItem(_prodTable);

    isTrumpf = ProdPool::find(_prodTable.ProdPoolId).NDX_TRU_ItemType == NDXTRUMPFItemType::Item;

    if(!isTrumpf)
    {
        message = strFmt("@NDX:NDXTRUisNotTrumpf",_prodTable.ProdPoolId);
    }

    return [isTrumpf, message];
}
